export const v16TerritorialDirectBatchHandler = async () => {
  await ensureSourceRegistry();
  const [sources,states,cursors]=await Promise.all([db.list<SourceRecord>('radar_sources',{limit:160}),db.list<SourceScanState>('source_scan_state',{limit:160}),db.list<{position:number;updatedAt:string}>('motor3_cursor',{limit:1})]);
  const stateByKey=new Map(states.items.map(item=>[item.sourceKey,item]));
  const rank:Record<string,number>={'A+':0,A:1,B:2,C:3,D:4};
  const pool=sources.items.filter(s=>s.active&&s.mode==='public_scan'&&s.territories.some(p=>PILOT.includes(p))).sort((a,b)=>rank[sourcePriority(a)]-rank[sourcePriority(b)]||a.key.localeCompare(b.key));
  const start=Math.max(0,Number(cursors.items[0]?.position||0))%(pool.length||1); const selected=pool.length?Array.from({length:Math.min(8,pool.length)},(_,i)=>pool[(start+i)%pool.length]).filter((v,i,a)=>a.indexOf(v)===i):[];
  const before=await usableOfferSnapshot(); const scans=[] as SourceAudit[];
  for(const source of selected){const result=await scanPublicSource(source,stateByKey.get(source.key)); scans.push(result.audit); if(result.state){const {id,...record}=result.state; if(id) await db.update('source_scan_state',[{id,record}]); else await db.add('source_scan_state',[record]);}}
  if(scans.length) await db.add('source_audits',scans); const next=pool.length?(start+selected.length)%pool.length:0; if(cursors.items[0]?.id) await db.update('motor3_cursor',[{id:cursors.items[0].id,record:{position:next,updatedAt:new Date().toISOString()}}]); else await db.add('motor3_cursor',[{position:next,updatedAt:new Date().toISOString()}]);
  const after=await usableOfferSnapshot(); const found=scans.reduce((s,i)=>s+i.candidatesFound,0); const fresh=scans.reduce((s,i)=>s+i.newCandidates,0); const links=scans.reduce((s,i)=>s+i.linksSeen,0); const checkedAt=new Date().toISOString(); await db.add('source_audits',[{sourceKey:'motor-direct-batch',checkedAt,status:'ok',linksSeen:links,candidatesFound:found,newCandidates:fresh,message:`Fuentes directas lote · ${selected.map(s=>s.name).join(' | ')} · enlaces:${links} · encontrados:${found} · nuevos:${fresh} · siguiente:${next}`}]); await recordLiveStage('Fuentes directas lote',before,after,fresh,found); return {statusCode:200};
};

