async function socialTextOffers(post:Record<string,unknown>):Promise<Record<string,unknown>[]> {
  const content=String(post.content || post.caption || post.message || post.text || post.description || '').trim().replace(/\r\n?/g,'\n').slice(0,5000);
  const published=socialOriginalDate(post);
  const originalDate=socialSourceDate(published);
  const dateTs=originalDate ? Date.parse(originalDate) : undefined;
  const postUrl=normalizeText(post.post_url || post.url);
  if(!postUrl || !isSpecificJobResult('Aviso laboral',postUrl))return [];
  if(!dateTs || dateTs>Date.now() || Date.now()-dateTs>45*86400000)return [];
  if(content.length<30 || !/(se necesita|se busca|se requiere|buscamos|contrata|vacante|oferta laboral|postulaci[oó]n|postula|enviar (?:cv|curr[ií]culum)|trabajo disponible|reclutamiento|recepci[oó]n de cv|cupos laborales|personal para|se solicita personal)/i.test(content))return [];
  const extracted=await ai.extract({
    content,
    prompt:'Extrae SOLO ofertas laborales concretas disponibles en Chile y explícitas en el texto. Descarta noticias, ferias sin cargos concretos, cursos, anuncios antiguos, solicitudes de empleo y avisos sin vacante. Devuelve hasta tres vacantes diferentes. No inventes título, empresa, comuna de trabajo, contacto ni fecha límite. Si no hay empleos concretos devuelve isJobNotice=false y offers=[].',
    schema:{type:'object',properties:{
      isJobNotice:{type:'boolean'},
      offers:{type:'array',items:{type:'object',properties:{
        title:{type:'string'},company:{type:'string'},commune:{type:'string'},
        contact:{type:'string'},requirements:{type:'string'},deadline:{type:'string'}
      },required:['title','commune']}}
    },required:['isJobNotice','offers']},
    maxTokens:1000,thinkingMode:'FAST',cache:true
  });
  const data=(extracted.data&&typeof extracted.data==='object')?extracted.data as Record<string,unknown>:{};
  if(data.isJobNotice!==true||!Array.isArray(data.offers))return [];
  const compact=content.toLowerCase().replace(/[^0-9a-záéíóúñ@.]/g,'');
  const digits=content.replace(/\D/g,'');
  const findings:Record<string,unknown>[]=[];
  for(const item of data.offers.slice(0,3)){
    if(!item||typeof item!=='object')continue;
    const offer=item as Record<string,unknown>;
    const title=normalizeText(offer.title),commune=normalizeText(offer.commune);
    if(title.length<3)continue;
    const claimedContact=normalizeText(offer.contact);
    const contactDigits=claimedContact.replace(/\D/g,'');
    const contactSupported=claimedContact&&(compact.includes(claimedContact.toLowerCase().replace(/[^0-9a-záéíóúñ@.]/g,''))||(contactDigits.length>=8&&digits.includes(contactDigits)));
    const deadline=normalizeText(offer.deadline);
    const deadlineTs=parseDiscoveryDate(deadline);
    if(deadlineTs&&deadlineTs<Date.now())continue;
    findings.push(preservedSocialFinding({postUrl,postDate:published,extractedAt:new Date().toISOString(),medium:'text',title,company:normalizeText(offer.company),commune,contact:contactSupported?claimedContact:'',requirements:normalizeText(offer.requirements),deadline,text:content}));
  }
  return findings;
}

