  if (!clean) return null;
  const host = new URL(clean).hostname.replace(/^www\./,'');
  if (LOCAL_PUBLISHERS[host]) return { name:LOCAL_PUBLISHERS[host],host,group:host };
  const portals:Record<string,[string,string]> = {
    'indeed.com':['Indeed','indeed'], 'cl.indeed.com':['Indeed','indeed'],
    'cl.computrabajo.com':['Computrabajo','computrabajo'], 'computrabajo.cl':['Computrabajo','computrabajo'],
    'linkedin.com':['LinkedIn','linkedin'], 'cl.linkedin.com':['LinkedIn','linkedin'],
    'laborum.cl':['Laborum','laborum'], 'opcionempleo.cl':['Opción Empleo','opcionempleo'],
    'chiletrabajos.cl':['Chiletrabajos','chiletrabajos'],
  };
  return portals[host] ? { name:portals[host][0],host,group:portals[host][1] } : null;
}

export function safePublicUrl(value:string, base?:string):string | null {
  try {
    if (typeof value!=='string' || value.length>2000) return null;
    const url = new URL(value, base);
    if (!['https:','http:'].includes(url.protocol) || url.username || url.password || url.port) return null;
    if ([...url.searchParams.keys()].some(key => /^(access_token|token|api_key|apikey|session|authorization)$/i.test(key))) return null;
    url.hash = '';
    for (const key of [...url.searchParams.keys()]) if (/^utm_/i.test(key) || ['fbclid','gclid','trk','trackingId'].includes(key)) url.searchParams.delete(key);
    url.searchParams.sort();
    return url.toString().length<=2000 ? url.toString() : null;
  } catch { return null; }
}

export function publicSourceAdapter(value:string):PublicAdapter | null {
  const clean = safePublicUrl(value);
  if (!clean) return null;
  const url = new URL(clean), host = url.hostname.replace(/^www\./,'');
  let name = '', identityUrl = '', family:PublicAdapter['family'] = 'portal';
  let match:RegExpMatchArray | null;
  if (host === 'chiletrabajos.cl' && /^\/trabajo\/[^/]+\/?$/.test(url.pathname)) {
    name = 'Chiletrabajos'; identityUrl = 'https://www.chiletrabajos.cl'+url.pathname.replace(/\/$/,'');
  } else if (['indeed.com','cl.indeed.com'].includes(host) && ['/viewjob','/rc/clk'].includes(url.pathname) && /^[a-f0-9]{16}$/i.test(url.searchParams.get('jk') || '')) {
    name = 'Indeed'; identityUrl = 'https://cl.indeed.com/viewjob?jk='+url.searchParams.get('jk')!.toLowerCase();
  } else if (['cl.computrabajo.com','computrabajo.cl'].includes(host) && (match = url.pathname.match(/^\/ofertas-de-trabajo\/(oferta-de-trabajo-de-[^/]+)\/?$/))) {
    name = 'Computrabajo'; identityUrl = 'https://cl.computrabajo.com/ofertas-de-trabajo/'+match[1];
  } else if (['linkedin.com','cl.linkedin.com'].includes(host) && (match = url.pathname.match(/^\/jobs\/view\/(?:[^/]*-)?(\d{6,})\/?$/))) {
    name = 'LinkedIn'; identityUrl = 'https://www.linkedin.com/jobs/view/'+match[1];
  } else if (host === 'laborum.cl' && (match = url.pathname.match(/^\/empleos\/[^/]+-(\d{5,})\.html\/?$/))) {
    name = 'Laborum'; identityUrl = 'https://www.laborum.cl/empleos/oferta-'+match[1]+'.html';
  } else if (host === 'opcionempleo.cl' && (match = url.pathname.match(/^\/jobad\/([a-z0-9]{12,})(?:\.html)?\/?$/i))) {
    name = 'Opción Empleo'; family = 'aggregator'; identityUrl = 'https://www.opcionempleo.cl/jobad/'+match[1].toLowerCase();
  } else if (LOCAL_PUBLISHERS[host] && url.pathname.split('/').filter(Boolean).length &&
      !/^\/(?:noticias?|concursos-publicos|direccion-de-fomento-productivo|category|categoria|tag|page|wp-json|feed)(?:\/\d+)?\/?$/.test(url.pathname) && !url.search) {
    name = LOCAL_PUBLISHERS[host]; family = 'local'; identityUrl = 'https://'+host+url.pathname.replace(/\/$/,'');
  }
  return name ? { name, family, identityUrl, verificationMethod:name+' individual page + matching JobPosting' } : null;
}

export function samePublicJob(left:string, right:string) {
  const first = publicSourceAdapter(left), second = publicSourceAdapter(right);
  return Boolean(first && second && first.identityUrl === second.identityUrl);
}

import { createHash } from 'node:crypto';
import { socialSourceDate } from './social-evidence';
import { publicSourceAdapter, safePublicUrl, samePublicJob } from './public-source-adapters';

type Data = Record<string, unknown>;
export type PublicVerification = {
  status:'verified' | 'review_ready' | 'pending' | 'rejected';
  reason:string;
  title?:string;
  company?:string;
  work_commune?:string;
  work_location_verified?:boolean;
  url?:string;
  source?:string;
  source_published_at?:string;
  valid_through?:string;
  application?:string;
  verification_method?:string;
  validity_method?:'explicit_deadline' | 'live_application';
  validity_evidence?:{ form_url:string; form_action:string; checked_at:string; source_sha256:string };
};

const SOURCE_WORK_PLACES = ['Angol','Collipulli','Ercilla','Renaico','Mininco','Los Sauces','Purén','Traiguén','Lumaco','Nacimiento','Negrete','Mulchén','Victoria'];
const sourceFold = (value:unknown) => String(value ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const sourceDecode = (value:string) => value.replace(/&(?:amp|quot|apos|lt|gt|nbsp);/g, entity => ({ '&amp;':'&','&quot;':'"','&apos;':"'",'&lt;':'<','&gt;':'>','&nbsp;':' ' }[entity] || entity));
export const publicText = (value:string) => sourceDecode(value.replace(/<[^>]*>/g,' ')).replace(/\s+/g,' ').trim();
const sourceObject = (value:unknown):value is Data => Boolean(value && typeof value === 'object' && !Array.isArray(value));

function visibleHtml(raw:string) {
  return raw.replace(/<(script|style|nav|header|footer|aside)\b[^>]*>[\s\S]*?<\/\1>/gi,'');
}

function attribute(tag:string, key:string) {
  const match = tag.match(new RegExp('(?:^|\\s)'+key+'\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))','i'));
  return match ? sourceDecode(match[1] ?? match[2] ?? match[3] ?? '') : '';
}

function postings(raw:string) {
  const result:Data[] = [];
  for (const script of raw.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)) {
    if (attribute(script[1],'type').toLowerCase() !== 'application/ld+json') continue;
    let nodes:unknown[];
    try { nodes = [JSON.parse(script[2])]; } catch { continue; }
    let visited = 0;
    while (nodes.length && visited++<2000) {
      const node = nodes.pop();
      if (Array.isArray(node)) nodes.push(...node);
      else if (sourceObject(node)) {
        const types = Array.isArray(node['@type']) ? node['@type'] : [node['@type']];
        if (types.includes('JobPosting')) result.push(node);
        nodes.push(...Object.values(node).filter(value => value && typeof value === 'object'));
      }
    }
  }
  return result;
}

function worksite(job:Data) {
  const locations = Array.isArray(job.jobLocation) ? job.jobLocation : [job.jobLocation];
  const found = new Set<string>();
  if (!locations.length) return null;
  for (const location of locations) {
    if (!sourceObject(location) || !sourceObject(location.address)) return null;
    const address = location.address;
    const country = sourceObject(address.addressCountry) ? address.addressCountry.name || address.addressCountry.identifier : address.addressCountry;
    if (!country || !['cl','chile'].includes(sourceFold(country).trim())) return null;
    const text = sourceFold(address.addressLocality);
    const places = SOURCE_WORK_PLACES.filter(place => new RegExp('\\b'+sourceFold(place)+'\\b').test(text));
    if (places.length===2 && places.includes('Mininco') && places.includes('Collipulli')) places.splice(places.indexOf('Collipulli'),1);
    if (!places.length) return null;
    for (const place of places) found.add(place);
  }
  return found.size===1 ? [...found][0] : null;
}

function applicationLink(raw:string, url:string) {
  for (const anchor of raw.matchAll(/<a\b([^>]*)>([\s\S]*?)<\/a>/gi)) {
    if (!/postul|aplicar|apply|envi.{0,20}(?:cv|curr[ií]culum)/i.test(publicText(anchor[2]))) continue;
    if (/\bdisabled\b|aria-disabled\s*=\s*["']true["']/i.test(anchor[1])) continue;
    const href = attribute(anchor[1],'href');
    if (/^mailto:[^@\s?]+@[^@\s?]+\.[^@\s?]+(?:\?.*)?$/i.test(href)) return href;
    const target = safePublicUrl(href,url);
    if (target?.startsWith('https:')) return target;
  }
  return null;
}

function liveApplicationForm(raw:string, url:string) {
  for (const form of raw.matchAll(/<form\b([^>]*)>([\s\S]*?)<\/form>/gi)) {
    if (/\bhidden\b|display\s*:\s*none|visibility\s*:\s*hidden/i.test(form[1])) continue;
    if (attribute(form[1],'method').toLowerCase() !== 'post' || /<fieldset\b[^>]*\bdisabled\b/i.test(form[2])) continue;
    const controls = [
      ...[...form[2].matchAll(/<button\b([^>]*)>([\s\S]*?)<\/button>/gi)].map(match => ({ kind:'button',attrs:match[1],label:match[2] })),
      ...[...form[2].matchAll(/<input\b([^>]*)>/gi)].map(match => ({ kind:'input',attrs:match[1],label:attribute(match[1],'value') })),
    ];
    const submit = controls.some(control => !/\bdisabled\b|\bhidden\b|display\s*:\s*none|visibility\s*:\s*hidden|aria-disabled\s*=\s*["']true["']/i.test(control.attrs) &&
      (attribute(control.attrs,'type') || (control.kind==='button'?'submit':'')).toLowerCase()==='submit' &&
      /postul|aplicar|apply|enviar.{0,15}(?:cv|curr[ií]culum)/i.test(publicText(control.label)));
    if (!submit) continue;
    const action = safePublicUrl(attribute(form[1],'action') || url,url);
    if (!action?.startsWith('https:') || new URL(action).hostname.replace(/^www\./,'') !== new URL(url).hostname.replace(/^www\./,'')) continue;
    if (/\/(?:login|signin|registro|subscribe|newsletter)(?:\/|$)/i.test(new URL(action).pathname)) continue;
    return action;
  }
  return null;
}

export function evaluatePublicJob(url:string, raw:string, finalUrl=url, status=200, now=Date.now()):PublicVerification {
  if ([404,410].includes(status)) return { status:'rejected',reason:'source_removed' };
  if (status!==200) return { status:'pending',reason:'HTTP '+status };
  const adapter = publicSourceAdapter(url);
  if (!adapter || !samePublicJob(url,finalUrl)) return { status:'pending',reason:'individual_source_identity_unconfirmed' };
  if (adapter.family==='aggregator') return { status:'pending',reason:'aggregator_requires_original_source' };
  if (Buffer.byteLength(raw,'utf8')>600000) return { status:'pending',reason:'source_byte_budget_exceeded' };
  const visible = visibleHtml(raw), body = publicText(visible);
  if (/verify you are human|access denied|unusual traffic|log in to view|iniciar sesi[oó]n para ver/i.test(body)) return { status:'pending',reason:'public_access_challenge' };
  if (/oferta (?:expirada|finalizada|cerrada)|postulaci[oó]n(?:es)? (?:cerradas?|finalizadas?)|esta oferta ya no|job (?:expired|closed)|no longer accepting applications/i.test(body)) return { status:'rejected',reason:'closed_notice' };
  const all = postings(raw);
  const matched = all.filter(job => {
    const entity = job.mainEntityOfPage;
    return [job.url,sourceObject(entity)?entity['@id']:entity].some(value => typeof value==='string' && samePublicJob(finalUrl,safePublicUrl(value,finalUrl) || ''));
  });
  const pageTitle = publicText(raw.match(/<title\b[^>]*>([\s\S]*?)<\/title>/i)?.[1] || '');
  const job = matched.length===1 ? matched[0] : !matched.length && all.length===1 &&
    !all[0].url && !all[0].mainEntityOfPage && typeof all[0].title==='string' &&
    sourceFold(pageTitle).includes(sourceFold(all[0].title)) ? all[0] : null;
  if (!job) return { status:'pending',reason:all.length?'ambiguous_jobposting':'structured_jobposting_missing' };
  const title = typeof job.title==='string' ? job.title.trim() : '';
  const employer = sourceObject(job.hiringOrganization) && typeof job.hiringOrganization.name==='string' ? job.hiringOrganization.name.trim() : '';
  const place = worksite(job);
  if (!title || title.length>300) return { status:'pending',reason:'job_title_missing' };
  if (!place) return { status:'pending',reason:'worksite_missing_or_multiple' };
  const base = { title,company:employer,work_commune:place,work_location_verified:true,url:finalUrl,source:adapter.name };
  const published = socialSourceDate(job.datePosted);
  const deadline = job.validThrough ? socialSourceDate(job.validThrough,true) : null;
  if (deadline && Date.parse(deadline)<=now) return { ...base,status:'rejected',reason:'expired_deadline' };
  if (!published || Date.parse(published)>now) return { ...base,status:'pending',reason:'source_date_missing_or_future' };
  const dated = { ...base,source_published_at:published };
  if (now-Date.parse(published)>45*86400000) return { ...dated,status:'pending',reason:'source_older_than_45_days' };
  if (!/oferta laboral|postul|requisitos|descripci[oó]n del (?:empleo|trabajo)|jornada|vacante|empleo|job|apply/i.test(body)) return { ...dated,status:'pending',reason:'hiring_text_missing' };
  if (job.validThrough && !deadline) return { ...dated,status:'review_ready',reason:'invalid_source_deadline' };
  const form = liveApplicationForm(visible,finalUrl), link = applicationLink(visible,finalUrl);
  const application = form || link;
  if (!employer || !application) return { ...dated,status:'review_ready',reason:'application_or_employer_requires_review' };
  if (!deadline && !form) return { ...dated,status:'review_ready',reason:'live_application_form_or_deadline_missing' };
  const result:PublicVerification = { ...dated,status:'verified',reason:deadline?'live_jobposting_with_deadline_and_application':'live_jobposting_with_enabled_application_form',
    application,valid_through:deadline || '',verification_method:adapter.verificationMethod,
    validity_method:deadline?'explicit_deadline':'live_application' };
  if (!deadline && form) result.validity_evidence = { form_url:finalUrl,form_action:form,checked_at:new Date(now).toISOString(),source_sha256:createHash('sha256').update(raw).digest('hex') };
  return result;
}

import { publicPublisher, safePublicUrl, samePublicJob } from './public-source-adapters';

export type PublicPage = { url:string; status:number; raw:string; mime:string; bytes:number; error?:string };

export async function fetchPublicPage(value:string, expectedJob?:string):Promise<PublicPage> {
  const clean = safePublicUrl(value), publisher = publicPublisher(value);
  if (!clean || !publisher) return { url:value,status:0,raw:'',mime:'',bytes:0,error:'publisher_not_allowed' };
  const signal = AbortSignal.timeout(6500);
  let current = clean;
  try {
    for (let redirect=0;redirect<4;redirect++) {
      const response = await fetch(current,{ headers:{ 'user-agent':'TrabajoCercaPublic/1.0','accept':'text/html,application/xhtml+xml,application/rss+xml,application/xml' },redirect:'manual',signal });
      if ([301,302,303,307,308].includes(response.status)) {
        const next = safePublicUrl(response.headers.get('location') || '',current);
        await response.body?.cancel();
        if (!next || publicPublisher(next)?.group !== publisher.group || (expectedJob && !samePublicJob(expectedJob,next))) return { url:current,status:response.status,raw:'',mime:'',bytes:0,error:'redirect_identity_unconfirmed' };
        current = next;continue;
      }
      const mime = (response.headers.get('content-type') || '').split(';')[0].toLowerCase();
      if (response.status!==200) { await response.body?.cancel();return { url:current,status:response.status,raw:'',mime,bytes:0 }; }
      if (!['text/html','application/xhtml+xml','application/rss+xml','application/xml','text/xml'].includes(mime)) {
        await response.body?.cancel();return { url:current,status:200,raw:'',mime,bytes:0,error:'document_requires_local_reader' };
      }
      const reader = response.body?.getReader();
      const parts:Uint8Array[] = [];
      let bytes = 0;
      if (reader) {
        while (true) {
          const chunk = await reader.read();if (chunk.done) break;
          bytes += chunk.value.byteLength;
          if (bytes>600000) { await reader.cancel();return { url:current,status:200,raw:'',mime,bytes,error:'source_byte_budget_exceeded' }; }
          parts.push(chunk.value);
        }
      } else {
        const raw = new Uint8Array(await response.arrayBuffer());bytes = raw.byteLength;
        if (bytes>600000) return { url:current,status:200,raw:'',mime,bytes,error:'source_byte_budget_exceeded' };
        parts.push(raw);
      }
      return { url:current,status:200,raw:Buffer.concat(parts).toString('utf8'),mime,bytes };
    }
    return { url:current,status:0,raw:'',mime:'',bytes:0,error:'redirect_budget_exhausted' };
  } catch {
    return { url:current,status:0,raw:'',mime:'',bytes:0,error:signal.aborted?'source_timeout':'source_unavailable' };
  }
}

import { db } from '@appdeploy/sdk';
import { createHash } from 'node:crypto';
import { currentPublicFeedManifest, registerPublicFeedChange } from './public-feed';
import { publicPublisher, publicSourceAdapter, safePublicUrl } from './public-source-adapters';
import { evaluatePublicJob, publicText, type PublicVerification } from './public-source-verifier';
import { fetchPublicPage } from './public-source-http';

export type FreeSource = { key:string; name:string; url:string; territory:string };
type ScanState = { position:number; queues:Record<string,string[]>; seen:Record<string,string[]>;
  pending:Array<{ url:string; source:string }>; checkedAt?:string; runId?:string; summary?:Record<string,unknown> };
type Stored = Record<string,unknown>;
const CURSOR = 'free_public_source_cursor';
const SEEDS = 'free_public_seed_state';
const hash = (value:string) => createHash('sha256').update(value).digest('hex');

export function publicPageLinks(raw:string, origin:string) {
  const candidates = new Map<string,string>(), archives = new Set<string>();
  for (const anchor of raw.matchAll(/<a\b([^>]*)href\s*=\s*["']([^"']+)["']([^>]*)>([\s\S]*?)<\/a>/gi)) {
    const url = safePublicUrl(anchor[2].replace(/&amp;/g,'&'),origin);
    if (!url) continue;
    const alt = [...anchor[4].matchAll(/\balt=["']([^"']+)["']/gi)].map(match => match[1]).join(' ');
    const title = publicText(anchor[4]+' '+alt);
    const adapter = publicSourceAdapter(url);
    if (adapter && (adapter.family!=='local' || /ofertas? laboral|vacante|se (?:busca|necesita|requiere)|omil|postul|concurso|empleo|trabajo/i.test(title+' '+url))) candidates.set(url,title.slice(0,200));
    if (publicPublisher(url)?.group===publicPublisher(origin)?.group &&
        (/\brel=["']next["']/i.test(anchor[1]+' '+anchor[3]) || /\/page\/\d+|[?&](?:page|paged)=\d+/i.test(url))) archives.add(url);
  }
  return { candidates:[...candidates].slice(0,40).map(([url,title]) => ({ url,title })),archives:[...archives].slice(0,5) };
}

export function verifiedPublicRecord(offer:PublicVerification, now=Date.now()):Stored {
  if (offer.status!=='verified' || !offer.url || !offer.title || !offer.company || !offer.work_commune || !offer.source_published_at) throw new Error('Incomplete public verification');
  const expiry = offer.valid_through || new Date(Date.parse(offer.source_published_at)+45*86400000).toISOString();
  return { kind:'job_offer',origin:'radar',title:offer.title,company:offer.company,
    workLocation:offer.work_commune,workCommunes:[offer.work_commune],recruitmentZones:[],recruitmentCommunes:[],
    area:'Fuente pública',status:'Verificada',date:new Date(offer.source_published_at).toLocaleDateString('es-CL',{ day:'2-digit',month:'short',year:'numeric',timeZone:'America/Santiago' }),source:offer.source,
    sourceDomain:new URL(offer.url).hostname,sourcePublishedAt:offer.source_published_at,
    sourceValidThrough:offer.valid_through || null,validityMethod:offer.validity_method || 'explicit_deadline',
    expiresAt:expiry,url:offer.url,note:(offer.valid_through?'Postulación comprobada en la fuente: ':'Formulario habilitado comprobado; la fuente no informa cierre: ')+offer.application,
    tags:[],visual:'field',icon:'work',review:false,verified:true,active:true,
    createdAt:new Date(now).toISOString(),discoveredBy:'free-public-sources-v1',
    verificationCheckedAt:new Date(now).toISOString(),verifiedAt:new Date(now).toISOString(),
    verificationMethod:offer.verification_method,verificationReason:offer.reason };
}

async function saveOffer(offer:PublicVerification, now:number) {
  const adapter = publicSourceAdapter(offer.url || '');
  if (!adapter || adapter.family==='aggregator') throw new Error('Unconfirmed offer identity');
  const identity = hash(adapter.identityUrl), table = 'radar_external_'+identity.slice(0,32);
  const previous = (await db.list<Stored>(table,{ limit:2 })).items;
  if (previous.length>1 || previous[0] && previous[0].externalIdentity!==identity) throw new Error('Public identity conflict; preserve history');
  const old = previous[0], { id:_id,...fields } = old || {};
  const record = { ...fields,...verifiedPublicRecord(offer,now),createdAt:old?.createdAt || new Date(now).toISOString(),
    externalIdentity:identity,externalVerifiedAt:new Date(now).toISOString() };
  if (Buffer.byteLength(JSON.stringify(record))>230*1024) throw new Error('Public offer exceeds byte budget');
  let id = old?.id;
  if (id) {
    const [ok] = await db.update(table,[{ id,record }]);
    if (!ok) throw new Error('Public offer update failed');
  } else {
    const [created] = await db.tx.add(table,[{ ...record,id:'free-'+identity.slice(0,40) }]);
    if (!created) throw new Error('Public offer already exists; reconcile before advancing');
    id = created;
  }
  await registerPublicFeedChange(table,id);
  return { table,id,url:offer.url };
}

export async function runFreePublicSources(sources:FreeSource[], requestId:string, now=Date.now()) {
  if (!/^[A-Za-z0-9_-]{12,128}$/.test(requestId)) throw new Error('Invalid public scan request ID');
  const receiptId = hash(requestId);
  const [completed] = await db.get<Stored>('free_public_source_runs',[receiptId],{ consistent:true });
  if (completed) return { ...(completed.summary as Stored),replayed:true,providerCalls:0 };
  const current = (await db.list<ScanState>(CURSOR,{ limit:1 })).items[0];
  if (current?.runId===requestId) return { ...current.summary,replayed:true,providerCalls:0 };
  if (!sources.length) throw new Error('No reviewed public sources');
  const [lease] = await db.tx.add('free_public_run_leases',[{ id:String(Math.floor(now/900000)),requestId,startedAt:new Date(now).toISOString() }]);
  if (!lease) return { deferred:true,reason:'public_scan_cooldown',providerCalls:0,nextAllowedAt:new Date((Math.floor(now/900000)+1)*900000).toISOString() };
  const state:ScanState = current ? structuredClone(current) : { position:0,queues:{},seen:{},pending:[] };
  const seenPending = new Set(state.pending.map(item => item.url));
  const audits:Stored[] = [],receipts:Stored[] = [];
  const changedSeeds = new Map<string,{ previous:Stored | null; record:Stored }>();
  let reads = 0, roots = 0;
  const started = Date.now();
  while (reads<5 && roots<Math.min(5,sources.length) && Date.now()-started<35000) {
    const source = sources[state.position%sources.length];
    const seedId = hash(source.key);
    const [previousSeed] = await db.get<Stored>(SEEDS,[seedId],{ consistent:true });
    let queue = (previousSeed?.queue as string[] | undefined) || state.queues[source.key];
    let seen = (previousSeed?.seen as string[] | undefined) || state.seen[source.key] || [];
    if (!queue?.length) { queue=[source.url];seen=[]; }
    const url = queue[0], page = await fetchPublicPage(url);reads++;roots++;
    const audit:Stored = { source:source.name,territory:source.territory,url,http:page.status,
      error:page.error || null,coverageComplete:false,candidates:0 };
    if (page.status===200 && !page.error) {
      const links = publicPageLinks(page.raw,page.url);
      if (publicSourceAdapter(page.url) && !seenPending.has(page.url)) links.candidates.unshift({ url:page.url,title:'' });
      for (const item of links.candidates) if (!seenPending.has(item.url) && state.pending.length<100) {
        state.pending.push({ url:item.url,source:source.name });seenPending.add(item.url);
      }
      seen = [...new Set([...seen,url])].slice(-64);
      queue = [...new Set([...queue.slice(1),...links.archives,...links.candidates.filter(item => publicSourceAdapter(item.url)?.family==='local').map(item => item.url)])]
        .filter(item => !seen.includes(item)).slice(0,30);
      audit.candidates = links.candidates.length;
    }
    const seed = { id:seedId,key:source.key,queue,seen,revision:Number(previousSeed?.revision || 0)+1,checkedAt:new Date(now).toISOString() };
    if (Buffer.byteLength(JSON.stringify(seed))>230*1024) throw new Error('Source history checkpoint byte budget exceeded');
    changedSeeds.set(seedId,{ previous:previousSeed,record:seed });
    audits.push(audit);state.position=(state.position+1)%sources.length;
  }
  let verified = 0;
  const reviewed:Stored[] = [];
  while (reads<8 && state.pending.length && reviewed.length<3 && Date.now()-started<50000) {
    const candidate = state.pending[0];
    const page = await fetchPublicPage(candidate.url,candidate.url);reads++;
    let result = page.error ? { status:'pending',reason:page.error } as PublicVerification : evaluatePublicJob(candidate.url,page.raw,page.url,page.status,now);
    if (result.reason==='aggregator_requires_original_source') {
      const originals = publicPageLinks(page.raw,page.url).candidates.filter(item => publicSourceAdapter(item.url)?.family!=='aggregator');
      if (originals.length===1 && reads<8) {
        const original = originals[0].url, originalPage = await fetchPublicPage(original,original);reads++;
        result = originalPage.error ? { status:'pending',reason:originalPage.error } : evaluatePublicJob(original,originalPage.raw,originalPage.url,originalPage.status,now);
      }
    }
    if (result.status==='verified') { receipts.push(await saveOffer(result,now));verified++; }
    reviewed.push({ url:candidate.url,status:result.status,reason:result.reason });
    // The immutable run receipt retains every reviewed result and source failure.
    state.pending.shift();
  }
  const summary = { checkedAt:new Date(now).toISOString(),sourcesRead:roots,httpReads:reads,
    noticesChecked:reviewed.length,verified,stored:receipts.length,published:0,providerCalls:0,
    pending:state.pending.length,nextSource:state.position,coverageComplete:false,audits,reviewed,receipts };
  state.summary=summary;state.checkedAt=summary.checkedAt;state.runId=requestId;
  state.queues={};state.seen={};
  const { id:_id,...payload } = state as ScanState & { id?:string };
  if (Buffer.byteLength(JSON.stringify(payload))>230*1024) throw new Error('Public source checkpoint byte budget exceeded');
  const checkpoint = current ? db.tx.update(CURSOR,[{ id:current.id,record:payload,if:{ runId:current.runId } }]) : db.tx.add(CURSOR,[{ ...payload,id:'cursor' }]);
  const receipt = db.tx.add('free_public_source_runs',[{ id:receiptId,requestId,summary }]);
  const seedWrites = [...changedSeeds].map(([id,seed]) => seed.previous ? db.tx.update(SEEDS,[{ id,record:seed.record,if:{ revision:seed.previous.revision } }]) : db.tx.add(SEEDS,[seed.record]));
  const [saved,recorded] = await db.transact([checkpoint,receipt,...seedWrites]);
  if (!saved[0] || !recorded[0]) throw new Error('Public source checkpoint and audit receipt were not committed');
  return summary;
}

export async function freePublicSourceStatus() {
  const current = (await db.list<ScanState>(CURSOR,{ limit:1 })).items[0];
  const snapshot = current ? await currentPublicFeedManifest() : null;
  const receipts = Array.isArray(current?.summary?.receipts) ? current.summary.receipts as Stored[] : [];
  const visible = snapshot ? receipts.filter(receipt => snapshot.manifest.pages.some(page => page.keys.includes(String(receipt.table)+':'+String(receipt.id)))) : [];
  return { readOnly:true,providerCalls:0,initialized:Boolean(current),summary:current?.summary || null,
    publishedConfirmed:snapshot ? visible.length : null,feedManifestId:snapshot?.manifestId || null,
    historicalCoverageComplete:false,pending:current?.pending.length ?? null,checkedAt:current?.checkedAt || null };
}

